Object.assign(TPREF,{"exer":[[["1CO",6,19,20],["ROM",12,1,1]],[["1CO",9,24,27]],[["1TI",4,7,8]],[["HEB",12,1,2]],[["2TI",4,7,8],["PHI",3,13,14]],[["2TI",2,5,5]],[["PSA",18,32,34],["ISA",40,31,31]],[["GEN",5,24,24],["MIC",6,8,8]],[["HEB",12,12,13],["ISA",35,3,4]]],"work":[[["GEN",2,15,15]],[["PRO",6,6,11]],[["PRO",10,4,5],["PRO",12,24,24]],[["COL",3,23,24]],[["1TH",4,11,12],["2TH",3,10,12]],[["PRO",31,17,20]],[["PSA",127,1,1],["PSA",90,17,17]],[["DEU",24,14,15],["JAM",5,4,4]],[["MAR",6,3,3],["MAT",13,55,55]]],"give":[[["2CO",9,6,8]],[["MAT",25,35,40]],[["LUK",10,30,37]],[["MAR",12,41,44]],[["ACT",20,35,35],["PRO",19,17,17]],[["JOH",13,12,15],["MAR",10,43,45]],[["HEB",13,1,2],["ROM",12,13,13]],[["ACT",2,44,47],["1JO",3,17,18]]],"speech":[[["EPH",4,29,29]],[["JAM",3,2,10]],[["JAM",1,19,20]],[["PRO",15,1,1],["PRO",15,4,4]],[["PSA",141,3,3],["PSA",19,14,14]],[["MAT",5,37,37],["EPH",4,25,25]],[["MAT",7,1,5]],[["COL",4,6,6],["PRO",25,11,11]]],"joy":[[["1TH",5,16,18]],[["LUK",17,12,19]],[["PSA",103,1,5]],[["PSA",118,24,24],["PSA",92,1,2]],[["PHI",4,4,5]],[["PHI",4,11,13]],[["GAL",5,22,23]],[["PSA",136,1,9]]]});
const HBTX={"es":{"exer":[["El cuerpo, templo del Espíritu","Cuidar el cuerpo es una forma de gratitud: no es nuestro, es templo del Espíritu Santo. San Pablo invita a ofrecerlo a Dios como un culto vivo. El ejercicio con medida forma parte de ese cuidado."],["Corred de manera que lo ganéis","San Pablo conocía los juegos de Corinto: los atletas se entrenan y se dominan en todo para ganar una corona que se marchita. El deporte enseña disciplina, y la vida cristiana la pide para una corona que no se marchita."],["El ejercicio es útil","Pablo no desprecia el ejercicio: dice que aprovecha, aunque la piedad aprovecha para todo. Es una invitación a ordenar las prioridades: entrenar el cuerpo sin descuidar el alma."],["Correr con paciencia la carrera","La vida es una carrera de fondo: hay que soltar lo que pesa y correr con constancia, con la mirada puesta en Jesús. Lo importante no es la velocidad, sino no abandonar."],["He terminado la carrera","Al final de su vida, Pablo dice que ha peleado la buena batalla y ha terminado la carrera. Olvidando lo que queda atrás, se lanza hacia la meta. Es el espíritu de quien no se rinde."],["Competir según las reglas","El atleta no recibe la corona si no compite según las reglas. El juego limpio, el respeto al rival y la honestidad también son parte del testimonio cristiano."],["Fuerza y pies de ciervo","Dios es quien ciñe de fuerza y da pies ligeros como los del ciervo. El esfuerzo físico puede vivirse como acción de gracias por la salud y las fuerzas recibidas."],["Caminar con Dios","Caminar es el ejercicio más sencillo y uno de los más bíblicos: Enoc caminó con Dios, y Miqueas resume la fe en caminar humildemente con Él. Un paseo puede ser también un rato de oración."],["Fortaleced las rodillas débiles","Para quien empieza, vuelve tras una lesión o se siente sin fuerzas: Dios anima a fortalecer las manos cansadas y a enderezar el camino. Cada pequeño paso cuenta."]],"work":[["Para cultivarlo y cuidarlo","Antes del pecado, Dios ya confía al hombre el jardín para cultivarlo y cuidarlo. El trabajo no es un castigo: es colaborar con la obra de Dios."],["Mira la hormiga","La hormiga trabaja sin que nadie la vigile y prepara su alimento a tiempo. Proverbios invita a la constancia y a vencer la pereza con pequeños pasos."],["La mano diligente","La diligencia da fruto y la desidia empobrece. No se trata de vivir para trabajar, sino de hacer bien lo que nos toca."],["Como para el Señor","«Todo lo que hagáis, hacedlo de corazón, como para el Señor». Hasta la tarea más humilde gana valor cuando se ofrece a Dios."],["Trabajar con las propias manos","San Pablo, que fabricaba tiendas, pide trabajar con sosiego y ganarse el propio pan. El trabajo honrado da dignidad y libertad."],["La mujer fuerte","Proverbios elogia a una mujer trabajadora y emprendedora que además abre la mano al pobre. El buen trabajo y la generosidad van juntos."],["Confirma la obra de nuestras manos","Si el Señor no construye la casa, en vano trabajan los albañiles. Pedimos a Dios que confirme la obra de nuestras manos: el esfuerzo humano necesita su bendición."],["El jornal justo","La Ley manda pagar al trabajador el mismo día, y Santiago denuncia el salario retenido. La justicia también se vive en el trabajo."],["Jesús, el carpintero","Jesús pasó la mayor parte de su vida trabajando como artesano en Nazaret. Su vida oculta santifica el trabajo de cada día."]],"give":[["Dios ama al que da con alegría","Quien siembra con generosidad, cosecha con generosidad. Dios no mira la cantidad, sino el corazón: dar con alegría es ya un regalo para quien da."],["Lo hicisteis conmigo","Dar de comer, vestir, visitar al enfermo y al preso: Jesús se identifica con los más pequeños. Cada gesto de servicio es un encuentro con Él."],["El buen samaritano","Quien ayuda no pregunta si el herido es de los suyos. Jesús termina la parábola con una tarea: «Ve, y haz tú lo mismo»."],["La ofrenda de la viuda","Dos pequeñas monedas valen más que grandes donativos, porque la viuda dio todo lo que tenía. La generosidad se mide por el amor, no por la cifra."],["Más dichoso es dar que recibir","Pablo recuerda estas palabras de Jesús, y Proverbios dice que quien da al pobre presta al Señor. Dar libera el corazón."],["Lavar los pies","Jesús lava los pies de sus discípulos y les pide hacer lo mismo. El que quiera ser grande, que sea servidor: el servicio es la grandeza cristiana."],["La hospitalidad","«No os olvidéis de la hospitalidad», porque algunos, sin saberlo, hospedaron ángeles. Abrir la casa y la mesa es una forma muy concreta de amar."],["Compartir los bienes","La primera comunidad lo ponía todo en común y nadie pasaba necesidad. San Juan pide amar no de palabra, sino con obras y de verdad."]],"speech":[["Palabras que edifican","Que no salga de vuestra boca ninguna palabra dañina, sino la que sirva para edificar. Antes de hablar, conviene preguntarse si lo que voy a decir ayuda."],["Domar la lengua","La lengua es pequeña como el timón de un barco, pero puede encender un gran bosque. Santiago pide coherencia: de la misma boca no deberían salir bendición y maldición."],["Pronto para oír, tardo para hablar","Escuchar más y hablar menos, y no dejarse llevar por la ira. Es un consejo sencillo que cambia muchas conversaciones."],["La respuesta suave","La respuesta amable calma la ira, y la palabra dura la enciende. Una lengua apacible es árbol de vida."],["Pon guarda a mi boca","El salmista pide a Dios que vigile la puerta de sus labios y que sus palabras le agraden. Es una buena oración para empezar el día."],["Decir la verdad","Que vuestro sí sea sí y vuestro no sea no. Dejar la mentira y hablar con verdad al prójimo construye confianza."],["No juzguéis","Antes de señalar la mota en el ojo ajeno, conviene mirar la viga en el propio. Hablar de los demás con misericordia es un hábito cristiano muy exigente."],["Palabras con sal","Que vuestra palabra sea siempre amable, sazonada con sal. Una palabra dicha a su tiempo es como manzanas de oro en bandeja de plata."]],"joy":[["Dad gracias en todo","Estad siempre alegres, orad sin cesar, dad gracias en todo. Agradecer no niega los problemas, pero cambia la mirada sobre ellos."],["Uno volvió a dar gracias","De diez leprosos curados, solo uno volvió a agradecer. Jesús echa de menos a los demás: la gratitud completa el regalo."],["Bendice, alma mía, al Señor","«No olvides ninguno de sus beneficios». Hacer memoria de lo recibido es el principio de la gratitud."],["Este es el día que hizo el Señor","Cada día es un regalo para alegrarse en él. Es bueno anunciar por la mañana su misericordia y por la noche su fidelidad."],["Alegraos siempre en el Señor","San Pablo escribe desde la cárcel y repite: alegraos. La alegría cristiana no depende de las circunstancias, sino de saber que el Señor está cerca."],["He aprendido a contentarme","Pablo ha conocido la escasez y la abundancia, y ha aprendido a estar contento en ambas. Su secreto: «Todo lo puedo en Cristo que me fortalece»."],["El fruto del Espíritu","Amor, alegría, paz, paciencia, amabilidad, bondad, fidelidad, mansedumbre y dominio propio. Son hábitos que el Espíritu hace crecer poco a poco."],["Porque es eterna su misericordia","El salmo repite una y otra vez el mismo estribillo mientras recuerda las obras de Dios. Repetir la gratitud la graba en el corazón."]]},"en":{"exer":[["The body, temple of the Spirit","Caring for the body is a form of gratitude: it is not ours, it is a temple of the Holy Spirit. Saint Paul invites us to offer it to God as living worship. Exercise in moderation is part of that care."],["Run so as to win","Saint Paul knew the games of Corinth: athletes train and exercise self-control in everything to win a crown that withers. Sport teaches discipline, and the Christian life asks for it for a crown that never withers."],["Exercise is useful","Paul does not despise exercise: he says it profits, although godliness profits in everything. It invites us to order our priorities: training the body without neglecting the soul."],["Run with endurance","Life is a long-distance race: we must lay aside what weighs us down and run with perseverance, looking to Jesus. What matters is not speed, but not giving up."],["I have finished the race","At the end of his life, Paul says he has fought the good fight and finished the race. Forgetting what lies behind, he presses on toward the goal. It is the spirit of someone who never gives up."],["Competing by the rules","An athlete is not crowned unless he competes according to the rules. Fair play, respect for opponents and honesty are also part of Christian witness."],["Strength and the feet of a deer","It is God who arms us with strength and makes our feet like a deer's. Physical effort can be lived as thanksgiving for the health and strength we have received."],["Walking with God","Walking is the simplest exercise and one of the most biblical: Enoch walked with God, and Micah sums up faith as walking humbly with him. A walk can also be a time of prayer."],["Strengthen the weak knees","For those who are starting out, coming back from an injury or feeling weak: God encourages us to strengthen tired hands and make straight paths. Every small step counts."]],"work":[["To work it and keep it","Before sin entered the world, God entrusted the garden to man to work it and take care of it. Work is not a punishment: it is cooperating with God's work."],["Look at the ant","The ant works without anyone watching and stores its food in time. Proverbs invites us to perseverance and to overcome laziness with small steps."],["The diligent hand","Diligence bears fruit and slackness brings poverty. It is not about living to work, but about doing well what is ours to do."],["As for the Lord","“Whatever you do, work at it with all your heart, as for the Lord.” Even the humblest task gains value when it is offered to God."],["Working with your own hands","Saint Paul, a tentmaker, asks us to work quietly and earn our own bread. Honest work gives dignity and freedom."],["The woman of strength","Proverbs praises a hard-working, enterprising woman who also opens her hand to the poor. Good work and generosity go together."],["Establish the work of our hands","Unless the Lord builds the house, its builders labour in vain. We ask God to establish the work of our hands: human effort needs his blessing."],["A fair wage","The Law commands paying the worker on the same day, and James denounces wages held back. Justice is also lived at work."],["Jesus the carpenter","Jesus spent most of his life working as a craftsman in Nazareth. His hidden life sanctifies everyday work."]],"give":[["God loves a cheerful giver","Whoever sows generously will reap generously. God looks not at the amount but at the heart: giving with joy is already a gift to the giver."],["You did it to me","Feeding the hungry, clothing the naked, visiting the sick and the prisoner: Jesus identifies with the least. Every act of service is an encounter with him."],["The Good Samaritan","The one who helps does not ask whether the wounded man is one of his own. Jesus ends the parable with a task: “Go and do likewise.”"],["The widow's offering","Two small coins are worth more than great gifts, because the widow gave all she had. Generosity is measured by love, not by the figure."],["It is more blessed to give","Paul recalls these words of Jesus, and Proverbs says that whoever gives to the poor lends to the Lord. Giving frees the heart."],["Washing feet","Jesus washes his disciples' feet and asks them to do the same. Whoever wants to be great must be a servant: service is Christian greatness."],["Hospitality","“Do not forget to show hospitality”, for some have entertained angels without knowing it. Opening our home and table is a very concrete way of loving."],["Sharing what we have","The first community held everything in common and no one was in need. Saint John asks us to love not in word but in deed and in truth."]],"speech":[["Words that build up","Let no harmful word come out of your mouth, but only what builds others up. Before speaking, it is worth asking whether what I am about to say helps."],["Taming the tongue","The tongue is small like a ship's rudder, but it can set a great forest on fire. James asks for consistency: blessing and cursing should not come from the same mouth."],["Quick to listen, slow to speak","Listen more, speak less and do not let anger carry you away. It is simple advice that changes many conversations."],["A gentle answer","A gentle answer turns away wrath, but a harsh word stirs it up. A soothing tongue is a tree of life."],["Set a guard over my mouth","The psalmist asks God to watch over the door of his lips and that his words may please him. It is a good prayer to begin the day."],["Telling the truth","Let your yes be yes and your no be no. Putting away falsehood and speaking truthfully to one another builds trust."],["Do not judge","Before pointing at the speck in another's eye, it is worth looking at the log in our own. Speaking of others with mercy is a very demanding Christian habit."],["Words seasoned with salt","Let your speech always be gracious, seasoned with salt. A word fitly spoken is like apples of gold in settings of silver."]],"joy":[["Give thanks in all things","Rejoice always, pray without ceasing, give thanks in all circumstances. Gratitude does not deny problems, but it changes how we see them."],["One came back to give thanks","Of ten lepers healed, only one came back to give thanks. Jesus misses the others: gratitude completes the gift."],["Bless the Lord, O my soul","“Forget not all his benefits.” Remembering what we have received is the beginning of gratitude."],["This is the day the Lord has made","Each day is a gift in which to rejoice. It is good to declare his steadfast love in the morning and his faithfulness at night."],["Rejoice in the Lord always","Saint Paul writes from prison and repeats: rejoice. Christian joy does not depend on circumstances, but on knowing that the Lord is near."],["I have learned to be content","Paul has known want and plenty, and has learned to be content in both. His secret: “I can do all things through Christ who strengthens me.”"],["The fruit of the Spirit","Love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control. These are habits the Spirit makes grow little by little."],["For his mercy endures for ever","The psalm repeats the same refrain again and again as it recalls God's works. Repeating gratitude engraves it on the heart."]]},"pt":{"exer":[["O corpo, templo do Espírito","Cuidar do corpo é uma forma de gratidão: não é nosso, é templo do Espírito Santo. São Paulo convida a oferecê-lo a Deus como culto vivo. O exercício com medida faz parte desse cuidado."],["Correi de modo a ganhar","São Paulo conhecia os jogos de Corinto: os atletas treinam e dominam-se em tudo para ganhar uma coroa que murcha. O desporto ensina disciplina, e a vida cristã pede-a para uma coroa que não murcha."],["O exercício é útil","Paulo não despreza o exercício: diz que é proveitoso, embora a piedade seja proveitosa para tudo. É um convite a ordenar as prioridades: treinar o corpo sem descuidar a alma."],["Correr com perseverança","A vida é uma corrida de fundo: é preciso largar o que pesa e correr com constância, com o olhar posto em Jesus. O importante não é a velocidade, mas não desistir."],["Terminei a corrida","No fim da vida, Paulo diz que combateu o bom combate e terminou a corrida. Esquecendo o que fica para trás, lança-se para a meta. É o espírito de quem não desiste."],["Competir segundo as regras","O atleta não recebe a coroa se não competir segundo as regras. O jogo limpo, o respeito pelo adversário e a honestidade também fazem parte do testemunho cristão."],["Força e pés de veado","É Deus quem nos cinge de força e nos dá pés ligeiros como os do veado. O esforço físico pode viver-se como ação de graças pela saúde e pelas forças recebidas."],["Caminhar com Deus","Caminhar é o exercício mais simples e um dos mais bíblicos: Enoque andou com Deus, e Miqueias resume a fé em caminhar humildemente com Ele. Um passeio pode ser também um tempo de oração."],["Fortalecei os joelhos vacilantes","Para quem começa, regressa de uma lesão ou se sente sem forças: Deus anima a fortalecer as mãos cansadas e a endireitar o caminho. Cada pequeno passo conta."]],"work":[["Para o cultivar e guardar","Antes do pecado, Deus já confia ao homem o jardim para o cultivar e guardar. O trabalho não é um castigo: é colaborar com a obra de Deus."],["Olha a formiga","A formiga trabalha sem que ninguém a vigie e prepara o alimento a tempo. Provérbios convida à constância e a vencer a preguiça com pequenos passos."],["A mão diligente","A diligência dá fruto e o desleixo empobrece. Não se trata de viver para trabalhar, mas de fazer bem aquilo que nos cabe."],["Como para o Senhor","«Tudo o que fizerdes, fazei-o de coração, como para o Senhor». Até a tarefa mais humilde ganha valor quando é oferecida a Deus."],["Trabalhar com as próprias mãos","São Paulo, que fabricava tendas, pede que se trabalhe com tranquilidade e se ganhe o próprio pão. O trabalho honesto dá dignidade e liberdade."],["A mulher forte","Provérbios elogia uma mulher trabalhadora e empreendedora que também abre a mão ao pobre. O bom trabalho e a generosidade andam juntos."],["Confirma a obra das nossas mãos","Se o Senhor não edificar a casa, em vão trabalham os que a constroem. Pedimos a Deus que confirme a obra das nossas mãos: o esforço humano precisa da sua bênção."],["O salário justo","A Lei manda pagar ao trabalhador no mesmo dia, e Tiago denuncia o salário retido. A justiça também se vive no trabalho."],["Jesus, o carpinteiro","Jesus passou a maior parte da vida a trabalhar como artesão em Nazaré. A sua vida oculta santifica o trabalho de cada dia."]],"give":[["Deus ama quem dá com alegria","Quem semeia com generosidade colhe com generosidade. Deus não olha à quantidade, mas ao coração: dar com alegria já é um presente para quem dá."],["A mim o fizestes","Dar de comer, vestir, visitar o doente e o preso: Jesus identifica-se com os mais pequenos. Cada gesto de serviço é um encontro com Ele."],["O bom samaritano","Quem ajuda não pergunta se o ferido é dos seus. Jesus termina a parábola com uma tarefa: «Vai e faz tu o mesmo»."],["A oferta da viúva","Duas pequenas moedas valem mais do que grandes donativos, porque a viúva deu tudo o que tinha. A generosidade mede-se pelo amor, não pelo número."],["Há mais alegria em dar","Paulo recorda estas palavras de Jesus, e Provérbios diz que quem dá ao pobre empresta ao Senhor. Dar liberta o coração."],["Lavar os pés","Jesus lava os pés aos discípulos e pede-lhes que façam o mesmo. Quem quiser ser grande, seja servo: o serviço é a grandeza cristã."],["A hospitalidade","«Não vos esqueçais da hospitalidade», porque alguns, sem o saberem, hospedaram anjos. Abrir a casa e a mesa é uma forma muito concreta de amar."],["Partilhar os bens","A primeira comunidade tinha tudo em comum e ninguém passava necessidade. São João pede que amemos não com palavras, mas com obras e em verdade."]],"speech":[["Palavras que edificam","Que da vossa boca não saia nenhuma palavra que magoe, mas a que sirva para edificar. Antes de falar, vale a pena perguntar se o que vou dizer ajuda."],["Domar a língua","A língua é pequena como o leme de um barco, mas pode incendiar uma grande floresta. Tiago pede coerência: da mesma boca não deviam sair bênção e maldição."],["Pronto para ouvir, lento para falar","Ouvir mais, falar menos e não se deixar levar pela ira. É um conselho simples que muda muitas conversas."],["A resposta branda","A resposta branda desvia o furor, e a palavra dura suscita a ira. Uma língua serena é árvore de vida."],["Põe guarda à minha boca","O salmista pede a Deus que vigie a porta dos seus lábios e que as suas palavras Lhe agradem. É uma boa oração para começar o dia."],["Dizer a verdade","Que o vosso sim seja sim e o vosso não seja não. Deixar a mentira e falar com verdade ao próximo constrói confiança."],["Não julgueis","Antes de apontar o argueiro no olho alheio, convém olhar a trave no próprio. Falar dos outros com misericórdia é um hábito cristão muito exigente."],["Palavras temperadas com sal","Que a vossa palavra seja sempre amável, temperada com sal. Uma palavra dita a seu tempo é como maçãs de ouro em salvas de prata."]],"joy":[["Dai graças em tudo","Estai sempre alegres, orai sem cessar, dai graças em tudo. Agradecer não nega os problemas, mas muda o olhar sobre eles."],["Só um voltou para agradecer","De dez leprosos curados, só um voltou para agradecer. Jesus sente a falta dos outros: a gratidão completa o presente."],["Bendiz, ó minha alma, o Senhor","«Não te esqueças de nenhum dos seus benefícios». Fazer memória do que se recebeu é o princípio da gratidão."],["Este é o dia que o Senhor fez","Cada dia é um presente para nele nos alegrarmos. É bom anunciar de manhã a sua misericórdia e de noite a sua fidelidade."],["Alegrai-vos sempre no Senhor","São Paulo escreve da prisão e repete: alegrai-vos. A alegria cristã não depende das circunstâncias, mas de saber que o Senhor está perto."],["Aprendi a contentar-me","Paulo conheceu a escassez e a abundância, e aprendeu a estar contente em ambas. O seu segredo: «Tudo posso n'Aquele que me fortalece»."],["O fruto do Espírito","Amor, alegria, paz, paciência, amabilidade, bondade, fidelidade, mansidão e domínio de si. São hábitos que o Espírito faz crescer pouco a pouco."],["Porque a sua misericórdia é eterna","O salmo repete uma e outra vez o mesmo refrão enquanto recorda as obras de Deus. Repetir a gratidão grava-a no coração."]]},"fr":{"exer":[["Le corps, temple de l’Esprit","Prendre soin du corps est une forme de gratitude : il ne nous appartient pas, il est le temple du Saint-Esprit. Saint Paul invite à l’offrir à Dieu comme un culte vivant. L’exercice pratiqué avec mesure fait partie de ce soin."],["Courez de manière à remporter le prix","Saint Paul connaissait les jeux de Corinthe : les athlètes s’entraînent et se maîtrisent en tout pour une couronne qui se fane. Le sport enseigne la discipline, et la vie chrétienne la demande pour une couronne qui ne se fane pas."],["L’exercice est utile","Paul ne méprise pas l’exercice : il dit qu’il est utile, même si la piété est utile à tout. C’est une invitation à ordonner les priorités : entraîner le corps sans négliger l’âme."],["Courir avec persévérance","La vie est une course de fond : il faut se débarrasser de ce qui alourdit et courir avec constance, les yeux fixés sur Jésus. L’important n’est pas la vitesse, mais de ne pas abandonner."],["J’ai achevé la course","À la fin de sa vie, Paul dit qu’il a combattu le bon combat et achevé la course. Oubliant ce qui est derrière, il court vers le but. C’est l’esprit de celui qui ne renonce pas."],["Lutter selon les règles","L’athlète n’est pas couronné s’il n’a pas lutté selon les règles. Le fair-play, le respect de l’adversaire et l’honnêteté font aussi partie du témoignage chrétien."],["La force et les pieds de la biche","C’est Dieu qui nous ceint de force et rend nos pieds semblables à ceux des biches. L’effort physique peut se vivre comme une action de grâce pour la santé et les forces reçues."],["Marcher avec Dieu","Marcher est l’exercice le plus simple et l’un des plus bibliques : Hénoch marcha avec Dieu, et Michée résume la foi en marcher humblement avec lui. Une promenade peut aussi être un temps de prière."],["Affermissez les genoux chancelants","Pour celui qui commence, revient d’une blessure ou se sent sans forces : Dieu encourage à fortifier les mains fatiguées et à redresser le chemin. Chaque petit pas compte."]],"work":[["Pour le cultiver et le garder","Avant le péché, Dieu confie déjà le jardin à l’homme pour le cultiver et le garder. Le travail n’est pas une punition : c’est collaborer à l’œuvre de Dieu."],["Regarde la fourmi","La fourmi travaille sans que personne la surveille et prépare sa nourriture à temps. Les Proverbes invitent à la constance et à vaincre la paresse par petits pas."],["La main diligente","La diligence porte du fruit et la négligence appauvrit. Il ne s’agit pas de vivre pour travailler, mais de bien faire ce qui nous revient."],["Comme pour le Seigneur","« Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur. » Même la tâche la plus humble prend de la valeur quand elle est offerte à Dieu."],["Travailler de ses mains","Saint Paul, fabricant de tentes, demande de travailler paisiblement et de gagner son propre pain. Le travail honnête donne dignité et liberté."],["La femme forte","Les Proverbes louent une femme travailleuse et entreprenante qui ouvre aussi la main au pauvre. Le bon travail et la générosité vont ensemble."],["Affermis l’ouvrage de nos mains","Si le Seigneur ne bâtit la maison, en vain travaillent ceux qui la bâtissent. Nous demandons à Dieu d’affermir l’ouvrage de nos mains : l’effort humain a besoin de sa bénédiction."],["Le juste salaire","La Loi ordonne de payer l’ouvrier le jour même, et Jacques dénonce le salaire retenu. La justice se vit aussi au travail."],["Jésus, le charpentier","Jésus a passé la plus grande partie de sa vie à travailler comme artisan à Nazareth. Sa vie cachée sanctifie le travail de chaque jour."]],"give":[["Dieu aime celui qui donne avec joie","Celui qui sème largement moissonnera largement. Dieu ne regarde pas la quantité, mais le cœur : donner avec joie est déjà un cadeau pour celui qui donne."],["C’est à moi que vous l’avez fait","Nourrir, vêtir, visiter le malade et le prisonnier : Jésus s’identifie aux plus petits. Chaque geste de service est une rencontre avec lui."],["Le bon Samaritain","Celui qui aide ne demande pas si le blessé est des siens. Jésus termine la parabole par une mission : « Va, et toi aussi, fais de même. »"],["L’offrande de la veuve","Deux petites pièces valent plus que de grandes offrandes, car la veuve a donné tout ce qu’elle avait. La générosité se mesure à l’amour, non au montant."],["Il y a plus de bonheur à donner","Paul rappelle cette parole de Jésus, et les Proverbes disent que celui qui donne au pauvre prête au Seigneur. Donner libère le cœur."],["Laver les pieds","Jésus lave les pieds de ses disciples et leur demande de faire de même. Celui qui veut être grand, qu’il soit serviteur : le service est la grandeur chrétienne."],["L’hospitalité","« N’oubliez pas l’hospitalité », car certains, sans le savoir, ont accueilli des anges. Ouvrir sa maison et sa table est une manière très concrète d’aimer."],["Partager ses biens","La première communauté mettait tout en commun et personne n’était dans le besoin. Saint Jean demande d’aimer non en paroles, mais en actes et en vérité."]],"speech":[["Des paroles qui construisent","Qu’aucune parole blessante ne sorte de votre bouche, mais celle qui sert à construire. Avant de parler, il vaut la peine de se demander si ce que je vais dire aide."],["Dompter la langue","La langue est petite comme le gouvernail d’un navire, mais elle peut embraser une grande forêt. Jacques demande la cohérence : bénédiction et malédiction ne devraient pas sortir de la même bouche."],["Prompt à écouter, lent à parler","Écouter davantage, parler moins et ne pas se laisser emporter par la colère. C’est un conseil simple qui change bien des conversations."],["La réponse douce","Une réponse douce calme la fureur, une parole dure excite la colère. Une langue apaisée est un arbre de vie."],["Mets une garde à ma bouche","Le psalmiste demande à Dieu de veiller sur la porte de ses lèvres et que ses paroles lui plaisent. C’est une bonne prière pour commencer la journée."],["Dire la vérité","Que votre oui soit oui et votre non, non. Renoncer au mensonge et dire la vérité à son prochain construit la confiance."],["Ne jugez pas","Avant de montrer la paille dans l’œil d’autrui, mieux vaut regarder la poutre dans le sien. Parler des autres avec miséricorde est une habitude chrétienne très exigeante."],["Des paroles assaisonnées de sel","Que votre parole soit toujours aimable, assaisonnée de sel. Une parole dite à propos est comme des pommes d’or sur des ciselures d’argent."]],"joy":[["Rendez grâce en toute chose","Soyez toujours dans la joie, priez sans cesse, rendez grâce en toute chose. Remercier ne nie pas les problèmes, mais change notre regard sur eux."],["Un seul revint rendre grâce","Sur dix lépreux guéris, un seul revint remercier. Jésus regrette l’absence des autres : la gratitude achève le don."],["Bénis le Seigneur, ô mon âme","« N’oublie aucun de ses bienfaits. » Faire mémoire de ce que l’on a reçu est le commencement de la gratitude."],["Voici le jour que fit le Seigneur","Chaque jour est un cadeau pour s’y réjouir. Il est bon d’annoncer le matin sa bonté et la nuit sa fidélité."],["Réjouissez-vous toujours dans le Seigneur","Saint Paul écrit depuis la prison et répète : réjouissez-vous. La joie chrétienne ne dépend pas des circonstances, mais de savoir que le Seigneur est proche."],["J’ai appris à être content","Paul a connu le manque et l’abondance, et il a appris à être content dans les deux. Son secret : « Je peux tout en celui qui me fortifie. »"],["Le fruit de l’Esprit","Amour, joie, paix, patience, bienveillance, bonté, fidélité, douceur et maîtrise de soi. Ce sont des habitudes que l’Esprit fait grandir peu à peu."],["Car éternel est son amour","Le psaume répète sans cesse le même refrain en rappelant les œuvres de Dieu. Répéter la gratitude la grave dans le cœur."]]},"it":{"exer":[["Il corpo, tempio dello Spirito","Prendersi cura del corpo è una forma di gratitudine: non è nostro, è tempio dello Spirito Santo. San Paolo invita a offrirlo a Dio come culto vivente. L’esercizio fatto con misura fa parte di questa cura."],["Correte in modo da conquistare il premio","San Paolo conosceva i giochi di Corinto: gli atleti si allenano e sono temperanti in tutto per una corona che appassisce. Lo sport insegna disciplina, e la vita cristiana la chiede per una corona che non appassisce."],["L’esercizio è utile","Paolo non disprezza l’esercizio: dice che è utile, anche se la pietà è utile a tutto. È un invito a ordinare le priorità: allenare il corpo senza trascurare l’anima."],["Correre con perseveranza","La vita è una corsa di fondo: bisogna deporre ciò che appesantisce e correre con costanza, tenendo lo sguardo su Gesù. Ciò che conta non è la velocità, ma non arrendersi."],["Ho terminato la corsa","Alla fine della vita, Paolo dice di aver combattuto la buona battaglia e terminato la corsa. Dimenticando ciò che sta alle spalle, si protende verso la meta. È lo spirito di chi non si arrende."],["Gareggiare secondo le regole","L’atleta non riceve la corona se non ha lottato secondo le regole. Il fair play, il rispetto dell’avversario e l’onestà fanno parte anche della testimonianza cristiana."],["Forza e piedi di cerva","È Dio che ci cinge di forza e rende i nostri piedi come quelli delle cerve. Lo sforzo fisico può essere vissuto come ringraziamento per la salute e le forze ricevute."],["Camminare con Dio","Camminare è l’esercizio più semplice e uno dei più biblici: Enoc camminò con Dio, e Michea riassume la fede nel camminare umilmente con lui. Una passeggiata può essere anche un momento di preghiera."],["Rendete salde le ginocchia vacillanti","Per chi comincia, torna da un infortunio o si sente senza forze: Dio incoraggia a rinvigorire le mani stanche e a raddrizzare la strada. Ogni piccolo passo conta."]],"work":[["Per coltivarlo e custodirlo","Prima del peccato, Dio affida già all’uomo il giardino perché lo coltivi e lo custodisca. Il lavoro non è un castigo: è collaborare all’opera di Dio."],["Guarda la formica","La formica lavora senza che nessuno la sorvegli e prepara il cibo per tempo. I Proverbi invitano alla costanza e a vincere la pigrizia a piccoli passi."],["La mano operosa","L’operosità porta frutto e la pigrizia impoverisce. Non si tratta di vivere per lavorare, ma di fare bene ciò che ci spetta."],["Come per il Signore","«Qualunque cosa facciate, fatela di cuore, come per il Signore». Anche il compito più umile acquista valore quando è offerto a Dio."],["Lavorare con le proprie mani","San Paolo, che fabbricava tende, chiede di lavorare con tranquillità e guadagnarsi il proprio pane. Il lavoro onesto dà dignità e libertà."],["La donna forte","I Proverbi lodano una donna laboriosa e intraprendente che apre anche la mano al povero. Il buon lavoro e la generosità vanno insieme."],["Rendi salda l’opera delle nostre mani","Se il Signore non costruisce la casa, invano vi faticano i costruttori. Chiediamo a Dio di rendere salda l’opera delle nostre mani: lo sforzo umano ha bisogno della sua benedizione."],["Il giusto salario","La Legge comanda di pagare l’operaio il giorno stesso, e Giacomo denuncia il salario trattenuto. La giustizia si vive anche nel lavoro."],["Gesù, il falegname","Gesù ha trascorso la maggior parte della sua vita lavorando come artigiano a Nazaret. La sua vita nascosta santifica il lavoro di ogni giorno."]],"give":[["Dio ama chi dona con gioia","Chi semina con larghezza, con larghezza raccoglierà. Dio non guarda la quantità, ma il cuore: donare con gioia è già un regalo per chi dona."],["L’avete fatto a me","Dare da mangiare, vestire, visitare il malato e il carcerato: Gesù si identifica con i più piccoli. Ogni gesto di servizio è un incontro con lui."],["Il buon samaritano","Chi aiuta non chiede se il ferito sia dei suoi. Gesù conclude la parabola con un compito: «Va’ e anche tu fa’ così»."],["L’offerta della vedova","Due spiccioli valgono più di grandi offerte, perché la vedova ha dato tutto ciò che aveva. La generosità si misura con l’amore, non con la cifra."],["Si è più beati nel dare","Paolo ricorda queste parole di Gesù, e i Proverbi dicono che chi dà al povero fa un prestito al Signore. Donare libera il cuore."],["Lavare i piedi","Gesù lava i piedi ai discepoli e chiede loro di fare lo stesso. Chi vuole essere grande sia servitore: il servizio è la grandezza cristiana."],["L’ospitalità","«Non dimenticate l’ospitalità», perché alcuni, senza saperlo, hanno accolto degli angeli. Aprire la casa e la tavola è un modo molto concreto di amare."],["Condividere i beni","La prima comunità metteva tutto in comune e nessuno era nel bisogno. San Giovanni chiede di amare non a parole, ma con i fatti e nella verità."]],"speech":[["Parole che edificano","Nessuna parola cattiva esca dalla vostra bocca, ma piuttosto parole buone che edifichino. Prima di parlare, conviene chiedersi se ciò che sto per dire aiuta."],["Domare la lingua","La lingua è piccola come il timone di una nave, ma può incendiare una grande foresta. Giacomo chiede coerenza: dalla stessa bocca non dovrebbero uscire benedizione e maledizione."],["Pronto ad ascoltare, lento a parlare","Ascoltare di più, parlare di meno e non lasciarsi trascinare dall’ira. È un consiglio semplice che cambia molte conversazioni."],["La risposta gentile","Una risposta gentile calma la collera, una parola pungente eccita l’ira. Una lingua mite è un albero di vita."],["Poni una guardia alla mia bocca","Il salmista chiede a Dio di sorvegliare la porta delle sue labbra e che le sue parole gli siano gradite. È una buona preghiera per iniziare la giornata."],["Dire la verità","Il vostro parlare sia sì, sì; no, no. Abbandonare la menzogna e dire la verità al prossimo costruisce fiducia."],["Non giudicate","Prima di indicare la pagliuzza nell’occhio altrui, conviene guardare la trave nel proprio. Parlare degli altri con misericordia è un’abitudine cristiana molto esigente."],["Parole condite con sale","La vostra parola sia sempre gentile, condita con sale. Una parola detta a suo tempo è come frutti d’oro su un vassoio d’argento."]],"joy":[["In ogni cosa rendete grazie","Siate sempre lieti, pregate ininterrottamente, in ogni cosa rendete grazie. Ringraziare non nega i problemi, ma cambia lo sguardo su di essi."],["Uno solo tornò a ringraziare","Dei dieci lebbrosi guariti, solo uno tornò a ringraziare. Gesù sente la mancanza degli altri: la gratitudine completa il dono."],["Benedici il Signore, anima mia","«Non dimenticare tutti i suoi benefici». Fare memoria di ciò che si è ricevuto è il principio della gratitudine."],["Questo è il giorno fatto dal Signore","Ogni giorno è un dono in cui rallegrarsi. È bello annunciare al mattino il suo amore e la sua fedeltà lungo la notte."],["Siate sempre lieti nel Signore","San Paolo scrive dal carcere e ripete: rallegratevi. La gioia cristiana non dipende dalle circostanze, ma dal sapere che il Signore è vicino."],["Ho imparato a bastare a me stesso","Paolo ha conosciuto la povertà e l’abbondanza, e ha imparato a essere contento in entrambe. Il suo segreto: «Tutto posso in colui che mi dà forza»."],["Il frutto dello Spirito","Amore, gioia, pace, magnanimità, benevolenza, bontà, fedeltà, mitezza e dominio di sé. Sono abitudini che lo Spirito fa crescere poco a poco."],["Perché il suo amore è per sempre","Il salmo ripete più e più volte lo stesso ritornello mentre ricorda le opere di Dio. Ripetere la gratitudine la incide nel cuore."]]},"de":{"exer":[["Der Leib, Tempel des Geistes","Für den Körper zu sorgen ist eine Form der Dankbarkeit: Er gehört nicht uns, er ist Tempel des Heiligen Geistes. Paulus lädt ein, ihn Gott als lebendigen Gottesdienst darzubringen. Maßvolle Bewegung gehört zu dieser Sorge."],["Lauft so, dass ihr gewinnt","Paulus kannte die Spiele von Korinth: Die Athleten trainieren und üben in allem Selbstbeherrschung für einen vergänglichen Kranz. Sport lehrt Disziplin, und das christliche Leben verlangt sie für einen unvergänglichen Kranz."],["Leibliche Übung ist nützlich","Paulus verachtet die Bewegung nicht: Er sagt, sie sei nützlich, auch wenn die Frömmigkeit zu allem nützlich ist. Eine Einladung, Prioritäten zu ordnen: den Körper trainieren, ohne die Seele zu vernachlässigen."],["Mit Ausdauer laufen","Das Leben ist ein Langstreckenlauf: Wir sollen ablegen, was uns beschwert, und mit Ausdauer laufen, den Blick auf Jesus gerichtet. Es zählt nicht das Tempo, sondern nicht aufzugeben."],["Ich habe den Lauf vollendet","Am Ende seines Lebens sagt Paulus, er habe den guten Kampf gekämpft und den Lauf vollendet. Er vergisst, was hinter ihm liegt, und jagt dem Ziel nach. Das ist der Geist dessen, der nicht aufgibt."],["Nach den Regeln kämpfen","Ein Athlet wird nicht gekrönt, wenn er nicht nach den Regeln kämpft. Fairplay, Respekt vor dem Gegner und Ehrlichkeit gehören auch zum christlichen Zeugnis."],["Kraft und Füße wie die Hirsche","Gott ist es, der uns mit Kraft umgürtet und unsere Füße den Hirschen gleich macht. Körperliche Anstrengung kann als Dank für Gesundheit und empfangene Kraft gelebt werden."],["Mit Gott gehen","Gehen ist die einfachste und eine der biblischsten Übungen: Henoch wandelte mit Gott, und Micha fasst den Glauben darin zusammen, demütig mit ihm zu gehen. Ein Spaziergang kann auch eine Zeit des Gebets sein."],["Stärkt die wankenden Knie","Für alle, die anfangen, nach einer Verletzung zurückkehren oder sich kraftlos fühlen: Gott ermutigt, die müden Hände zu stärken und den Weg gerade zu machen. Jeder kleine Schritt zählt."]],"work":[["Um ihn zu bebauen und zu bewahren","Schon vor dem Sündenfall vertraut Gott dem Menschen den Garten an, um ihn zu bebauen und zu bewahren. Arbeit ist keine Strafe: Sie ist Mitarbeit am Werk Gottes."],["Sieh die Ameise an","Die Ameise arbeitet, ohne dass jemand sie beaufsichtigt, und sammelt rechtzeitig ihre Nahrung. Die Sprichwörter laden zur Beständigkeit ein und dazu, die Trägheit in kleinen Schritten zu überwinden."],["Die fleißige Hand","Fleiß bringt Frucht, Lässigkeit macht arm. Es geht nicht darum, für die Arbeit zu leben, sondern das gut zu tun, was uns aufgetragen ist."],["Als dem Herrn","„Was ihr tut, das tut von Herzen als dem Herrn.“ Selbst die bescheidenste Aufgabe gewinnt an Wert, wenn sie Gott dargebracht wird."],["Mit den eigenen Händen arbeiten","Paulus, ein Zeltmacher, bittet darum, in Ruhe zu arbeiten und sein eigenes Brot zu verdienen. Ehrliche Arbeit schenkt Würde und Freiheit."],["Die tüchtige Frau","Die Sprichwörter loben eine fleißige, unternehmungslustige Frau, die auch dem Armen ihre Hand öffnet. Gute Arbeit und Großzügigkeit gehören zusammen."],["Das Werk unserer Hände fördere","Wenn der Herr nicht das Haus baut, arbeiten umsonst, die daran bauen. Wir bitten Gott, das Werk unserer Hände zu fördern: Menschliche Mühe braucht seinen Segen."],["Der gerechte Lohn","Das Gesetz befiehlt, den Arbeiter am selben Tag zu bezahlen, und Jakobus prangert den vorenthaltenen Lohn an. Gerechtigkeit wird auch in der Arbeit gelebt."],["Jesus, der Zimmermann","Jesus verbrachte den größten Teil seines Lebens als Handwerker in Nazaret. Sein verborgenes Leben heiligt die tägliche Arbeit."]],"give":[["Einen fröhlichen Geber hat Gott lieb","Wer reichlich sät, wird reichlich ernten. Gott schaut nicht auf die Menge, sondern auf das Herz: Fröhlich zu geben ist schon ein Geschenk für den Gebenden."],["Das habt ihr mir getan","Hungrige speisen, Nackte kleiden, Kranke und Gefangene besuchen: Jesus identifiziert sich mit den Geringsten. Jede Geste des Dienens ist eine Begegnung mit ihm."],["Der barmherzige Samariter","Wer hilft, fragt nicht, ob der Verletzte einer der Seinen ist. Jesus schließt das Gleichnis mit einem Auftrag: „Geh hin und tu desgleichen!“"],["Das Opfer der Witwe","Zwei kleine Münzen sind mehr wert als große Spenden, denn die Witwe gab alles, was sie hatte. Großzügigkeit misst sich an der Liebe, nicht an der Summe."],["Geben ist seliger als nehmen","Paulus erinnert an dieses Wort Jesu, und die Sprichwörter sagen, wer dem Armen gibt, leiht dem Herrn. Geben befreit das Herz."],["Die Füße waschen","Jesus wäscht seinen Jüngern die Füße und bittet sie, dasselbe zu tun. Wer groß sein will, sei Diener: Das Dienen ist christliche Größe."],["Gastfreundschaft","„Vergesst die Gastfreundschaft nicht“, denn manche haben, ohne es zu wissen, Engel beherbergt. Haus und Tisch zu öffnen ist eine sehr konkrete Weise zu lieben."],["Das Eigene teilen","Die erste Gemeinde hatte alles gemeinsam, und niemand litt Not. Johannes bittet, nicht mit Worten zu lieben, sondern in Tat und Wahrheit."]],"speech":[["Worte, die aufbauen","Kein böses Wort soll aus eurem Mund kommen, sondern eines, das aufbaut. Bevor ich spreche, lohnt sich die Frage, ob das, was ich sagen will, hilft."],["Die Zunge zähmen","Die Zunge ist klein wie das Ruder eines Schiffes, kann aber einen großen Wald in Brand setzen. Jakobus bittet um Stimmigkeit: Segen und Fluch sollten nicht aus demselben Mund kommen."],["Schnell zum Hören, langsam zum Reden","Mehr zuhören, weniger reden und sich nicht vom Zorn hinreißen lassen. Ein einfacher Rat, der viele Gespräche verändert."],["Die sanfte Antwort","Eine sanfte Antwort stillt den Zorn, ein kränkendes Wort erregt Grimm. Eine heilsame Zunge ist ein Baum des Lebens."],["Stelle eine Wache vor meinen Mund","Der Psalmist bittet Gott, die Tür seiner Lippen zu bewachen und dass seine Worte ihm gefallen. Ein gutes Gebet für den Beginn des Tages."],["Die Wahrheit sagen","Euer Ja sei ein Ja, euer Nein ein Nein. Die Lüge ablegen und mit dem Nächsten wahrhaftig reden baut Vertrauen auf."],["Richtet nicht","Bevor wir auf den Splitter im Auge des anderen zeigen, sollten wir den Balken im eigenen sehen. Barmherzig über andere zu sprechen ist eine sehr anspruchsvolle christliche Gewohnheit."],["Mit Salz gewürzt","Eure Rede sei allezeit freundlich und mit Salz gewürzt. Ein Wort, zur rechten Zeit geredet, ist wie goldene Äpfel auf silbernen Schalen."]],"joy":[["Seid dankbar in allen Dingen","Freut euch allezeit, betet ohne Unterlass, seid dankbar in allen Dingen. Dankbarkeit leugnet die Probleme nicht, aber sie verändert den Blick darauf."],["Nur einer kehrte um, um zu danken","Von zehn geheilten Aussätzigen kam nur einer zurück, um zu danken. Jesus vermisst die anderen: Dankbarkeit vollendet das Geschenk."],["Lobe den Herrn, meine Seele","„Vergiss nicht, was er dir Gutes getan hat.“ Sich an das Empfangene zu erinnern ist der Anfang der Dankbarkeit."],["Dies ist der Tag, den der Herr gemacht hat","Jeder Tag ist ein Geschenk, um sich daran zu freuen. Es ist gut, am Morgen seine Gnade und in der Nacht seine Treue zu verkünden."],["Freut euch im Herrn allezeit","Paulus schreibt aus dem Gefängnis und wiederholt: Freut euch. Christliche Freude hängt nicht von den Umständen ab, sondern davon, dass der Herr nahe ist."],["Ich habe gelernt, zufrieden zu sein","Paulus hat Mangel und Überfluss erlebt und gelernt, in beidem zufrieden zu sein. Sein Geheimnis: „Ich vermag alles durch den, der mich stark macht.“"],["Die Frucht des Geistes","Liebe, Freude, Friede, Geduld, Freundlichkeit, Güte, Treue, Sanftmut und Selbstbeherrschung. Gewohnheiten, die der Geist nach und nach wachsen lässt."],["Denn seine Güte währet ewiglich","Der Psalm wiederholt immer wieder denselben Kehrvers, während er Gottes Taten erzählt. Dankbarkeit zu wiederholen prägt sie ins Herz ein."]]},"el":{"exer":[["Το σώμα, ναός του Πνεύματος","Η φροντίδα του σώματος είναι μορφή ευγνωμοσύνης: δεν μας ανήκει, είναι ναός του Αγίου Πνεύματος. Ο Απόστολος Παύλος μάς καλεί να το προσφέρουμε στον Θεό ως ζωντανή λατρεία. Η άσκηση με μέτρο είναι μέρος αυτής της φροντίδας."],["Τρέξτε για να κερδίσετε","Ο Παύλος γνώριζε τους αγώνες της Κορίνθου: οι αθλητές προπονούνται και εγκρατεύονται σε όλα για ένα φθαρτό στεφάνι. Ο αθλητισμός διδάσκει πειθαρχία, και η χριστιανική ζωή τη ζητά για ένα άφθαρτο στεφάνι."],["Η σωματική άσκηση είναι ωφέλιμη","Ο Παύλος δεν περιφρονεί την άσκηση: λέει ότι ωφελεί, αν και η ευσέβεια ωφελεί σε όλα. Είναι πρόσκληση να βάλουμε σε τάξη τις προτεραιότητες: να ασκούμε το σώμα χωρίς να παραμελούμε την ψυχή."],["Τρέχουμε με υπομονή","Η ζωή είναι αγώνας αντοχής: πρέπει να αφήσουμε ό,τι μας βαραίνει και να τρέχουμε με επιμονή, με το βλέμμα στον Ιησού. Σημασία δεν έχει η ταχύτητα, αλλά να μην εγκαταλείψουμε."],["Τον δρόμο τετέλεκα","Στο τέλος της ζωής του, ο Παύλος λέει ότι αγωνίστηκε τον καλό αγώνα και τελείωσε τον δρόμο. Ξεχνώντας τα πίσω, τρέχει προς τον σκοπό. Είναι το πνεύμα εκείνου που δεν τα παρατά."],["Αγώνας με κανόνες","Ο αθλητής δεν στεφανώνεται αν δεν αγωνιστεί σύμφωνα με τους κανόνες. Το τίμιο παιχνίδι, ο σεβασμός στον αντίπαλο και η εντιμότητα είναι επίσης μέρος της χριστιανικής μαρτυρίας."],["Δύναμη και πόδια ελαφιού","Ο Θεός είναι εκείνος που μας περιζώνει με δύναμη και κάνει τα πόδια μας σαν του ελαφιού. Η σωματική προσπάθεια μπορεί να βιωθεί ως ευχαριστία για την υγεία και τις δυνάμεις που λάβαμε."],["Περπατώ με τον Θεό","Το περπάτημα είναι η πιο απλή άσκηση και από τις πιο βιβλικές: ο Ενώχ περπάτησε με τον Θεό, και ο Μιχαίας συνοψίζει την πίστη στο να πορεύεσαι ταπεινά μαζί Του. Ένας περίπατος μπορεί να γίνει και ώρα προσευχής."],["Στερεώστε τα παραλυμένα γόνατα","Για όποιον ξεκινά, επιστρέφει μετά από τραυματισμό ή νιώθει χωρίς δυνάμεις: ο Θεός ενθαρρύνει να ενισχύσουμε τα κουρασμένα χέρια και να ισιώσουμε τον δρόμο. Κάθε μικρό βήμα μετράει."]],"work":[["Για να τον εργάζεται και να τον φυλάει","Πριν από την πτώση, ο Θεός εμπιστεύεται ήδη στον άνθρωπο τον κήπο για να τον καλλιεργεί και να τον φυλάει. Η εργασία δεν είναι τιμωρία: είναι συνεργασία στο έργο του Θεού."],["Δες το μυρμήγκι","Το μυρμήγκι εργάζεται χωρίς να το επιβλέπει κανείς και ετοιμάζει έγκαιρα την τροφή του. Οι Παροιμίες καλούν στη σταθερότητα και στη νίκη της οκνηρίας με μικρά βήματα."],["Το επιμελές χέρι","Η επιμέλεια φέρνει καρπό και η αμέλεια φτωχαίνει. Δεν πρόκειται να ζούμε για να δουλεύουμε, αλλά να κάνουμε καλά ό,τι μας αναλογεί."],["Ως τω Κυρίω","«Ό,τι κάνετε, να το κάνετε με όλη σας την ψυχή, σαν για τον Κύριο». Ακόμη και η πιο ταπεινή εργασία αποκτά αξία όταν προσφέρεται στον Θεό."],["Εργάζομαι με τα χέρια μου","Ο Παύλος, που έφτιαχνε σκηνές, ζητά να εργαζόμαστε με ησυχία και να κερδίζουμε το ψωμί μας. Η τίμια εργασία δίνει αξιοπρέπεια και ελευθερία."],["Η γυναίκα η ανδρεία","Οι Παροιμίες επαινούν μια εργατική και δραστήρια γυναίκα που ανοίγει και το χέρι της στον φτωχό. Η καλή εργασία και η γενναιοδωρία πάνε μαζί."],["Κατεύθυνε τα έργα των χειρών μας","Αν ο Κύριος δεν οικοδομήσει το σπίτι, μάταια κοπιάζουν οι οικοδόμοι. Ζητούμε από τον Θεό να κατευθύνει τα έργα των χειρών μας: ο ανθρώπινος κόπος χρειάζεται την ευλογία Του."],["Ο δίκαιος μισθός","Ο Νόμος ορίζει να πληρώνεται ο εργάτης την ίδια μέρα, και ο Ιάκωβος καταγγέλλει τον παρακρατημένο μισθό. Η δικαιοσύνη βιώνεται και στην εργασία."],["Ο Ιησούς, ο τέκτων","Ο Ιησούς πέρασε το μεγαλύτερο μέρος της ζωής Του δουλεύοντας ως τεχνίτης στη Ναζαρέτ. Η κρυφή ζωή Του αγιάζει την καθημερινή εργασία."]],"give":[["Ιλαρόν δότην αγαπά ο Θεός","Όποιος σπέρνει πλούσια, πλούσια θα θερίσει. Ο Θεός δεν κοιτάζει την ποσότητα αλλά την καρδιά: το να δίνεις με χαρά είναι ήδη δώρο για εκείνον που δίνει."],["Εμοί εποιήσατε","Να ταΐζεις, να ντύνεις, να επισκέπτεσαι τον άρρωστο και τον φυλακισμένο: ο Ιησούς ταυτίζεται με τους ελάχιστους. Κάθε πράξη διακονίας είναι συνάντηση μαζί Του."],["Ο καλός Σαμαρείτης","Όποιος βοηθά δεν ρωτά αν ο τραυματίας είναι δικός του. Ο Ιησούς κλείνει την παραβολή με μια αποστολή: «Πήγαινε και κάνε κι εσύ το ίδιο»."],["Το δίλεπτο της χήρας","Δύο μικρά νομίσματα αξίζουν περισσότερο από μεγάλες προσφορές, γιατί η χήρα έδωσε όλα όσα είχε. Η γενναιοδωρία μετριέται με την αγάπη, όχι με το ποσό."],["Μακάριον εστί μάλλον διδόναι","Ο Παύλος θυμίζει αυτόν τον λόγο του Ιησού, και οι Παροιμίες λένε ότι όποιος δίνει στον φτωχό δανείζει στον Κύριο. Το να δίνεις ελευθερώνει την καρδιά."],["Το πλύσιμο των ποδιών","Ο Ιησούς πλένει τα πόδια των μαθητών Του και τους ζητά να κάνουν το ίδιο. Όποιος θέλει να γίνει μεγάλος, ας γίνει διάκονος: η διακονία είναι το χριστιανικό μεγαλείο."],["Η φιλοξενία","«Της φιλοξενίας μη επιλανθάνεσθε», γιατί κάποιοι, χωρίς να το ξέρουν, φιλοξένησαν αγγέλους. Να ανοίγεις το σπίτι και το τραπέζι σου είναι ένας πολύ συγκεκριμένος τρόπος αγάπης."],["Μοιράζομαι τα αγαθά","Η πρώτη κοινότητα τα είχε όλα κοινά και κανείς δεν είχε ανάγκη. Ο Ιωάννης ζητά να αγαπάμε όχι με λόγια, αλλά με έργα και με αλήθεια."]],"speech":[["Λόγια που οικοδομούν","Κανένας σάπιος λόγος να μη βγαίνει από το στόμα σας, αλλά ό,τι είναι καλό για οικοδομή. Πριν μιλήσω, αξίζει να ρωτήσω αν αυτό που θα πω βοηθά."],["Δαμάζω τη γλώσσα","Η γλώσσα είναι μικρή σαν το πηδάλιο του πλοίου, αλλά μπορεί να βάλει φωτιά σε ολόκληρο δάσος. Ο Ιάκωβος ζητά συνέπεια: από το ίδιο στόμα δεν πρέπει να βγαίνουν ευλογία και κατάρα."],["Ταχύς εις το ακούσαι, βραδύς εις το λαλήσαι","Να ακούμε περισσότερο, να μιλάμε λιγότερο και να μην παρασυρόμαστε από τον θυμό. Μια απλή συμβουλή που αλλάζει πολλές συζητήσεις."],["Η πράα απάντηση","Η πράα απάντηση καταλαγιάζει τον θυμό, ενώ ο σκληρός λόγος τον ανάβει. Η ήπια γλώσσα είναι δέντρο ζωής."],["Θου, Κύριε, φυλακήν τω στόματί μου","Ο ψαλμωδός ζητά από τον Θεό να φυλάει τη θύρα των χειλιών του και τα λόγια του να Του είναι ευάρεστα. Καλή προσευχή για να ξεκινά η μέρα."],["Λέω την αλήθεια","Το ναι σας να είναι ναι και το όχι σας όχι. Να αφήνουμε το ψέμα και να μιλάμε με αλήθεια στον πλησίον χτίζει εμπιστοσύνη."],["Μη κρίνετε","Πριν δείξουμε το άχυρο στο μάτι του άλλου, καλό είναι να δούμε το δοκάρι στο δικό μας. Να μιλάς για τους άλλους με ευσπλαχνία είναι μια πολύ απαιτητική χριστιανική συνήθεια."],["Λόγος αρτυμένος με αλάτι","Ο λόγος σας να είναι πάντοτε με χάρη, αρτυμένος με αλάτι. Ένας λόγος ειπωμένος στην ώρα του είναι σαν χρυσά μήλα σε ασημένιο δίσκο."]],"joy":[["Εν παντί ευχαριστείτε","Πάντοτε να χαίρεστε, αδιαλείπτως να προσεύχεστε, για όλα να ευχαριστείτε. Η ευγνωμοσύνη δεν αρνείται τα προβλήματα, αλλά αλλάζει το βλέμμα μας πάνω τους."],["Μόνο ένας γύρισε να ευχαριστήσει","Από τους δέκα λεπρούς που θεραπεύτηκαν, μόνο ένας γύρισε να ευχαριστήσει. Ο Ιησούς αναζητά τους άλλους: η ευγνωμοσύνη ολοκληρώνει το δώρο."],["Ευλόγει, η ψυχή μου, τον Κύριον","«Μην ξεχνάς καμία από τις ευεργεσίες Του». Η ανάμνηση όσων λάβαμε είναι η αρχή της ευγνωμοσύνης."],["Αύτη η ημέρα ην εποίησεν ο Κύριος","Κάθε μέρα είναι δώρο για να χαρούμε σε αυτήν. Είναι καλό να αναγγέλλουμε το πρωί το έλεός Του και τη νύχτα την πιστότητά Του."],["Χαίρετε εν Κυρίω πάντοτε","Ο Παύλος γράφει από τη φυλακή και επαναλαμβάνει: χαίρετε. Η χριστιανική χαρά δεν εξαρτάται από τις περιστάσεις, αλλά από το ότι ο Κύριος είναι κοντά."],["Έμαθα να είμαι αυτάρκης","Ο Παύλος γνώρισε τη στέρηση και την αφθονία, και έμαθε να είναι ικανοποιημένος και στις δύο. Το μυστικό του: «Τα πάντα ισχύω εν τω ενδυναμούντί με Χριστώ»."],["Ο καρπός του Πνεύματος","Αγάπη, χαρά, ειρήνη, μακροθυμία, χρηστότητα, αγαθοσύνη, πίστη, πραότητα, εγκράτεια. Είναι συνήθειες που το Πνεύμα αυξάνει λίγο λίγο."],["Ότι εις τον αιώνα το έλεος αυτού","Ο ψαλμός επαναλαμβάνει ξανά και ξανά την ίδια επωδό, θυμίζοντας τα έργα του Θεού. Η επανάληψη της ευγνωμοσύνης τη χαράζει στην καρδιά."]]},"ru":{"exer":[["Тело — храм Духа","Заботиться о теле — это форма благодарности: оно не наше, оно храм Святого Духа. Апостол Павел призывает приносить его Богу как живое служение. Умеренные физические упражнения — часть этой заботы."],["Бегите так, чтобы получить награду","Павел знал коринфские игры: атлеты тренируются и воздерживаются от всего ради тленного венца. Спорт учит дисциплине, а христианская жизнь требует её ради нетленного венца."],["Телесное упражнение полезно","Павел не презирает упражнения: он говорит, что они полезны, хотя благочестие полезно на всё. Это приглашение расставить приоритеты: тренировать тело, не забывая о душе."],["С терпением проходить поприще","Жизнь — это бег на длинную дистанцию: нужно сбросить всё, что тяготит, и бежать с терпением, взирая на Иисуса. Важна не скорость, а то, чтобы не сойти с дистанции."],["Течение совершил","В конце жизни Павел говорит, что подвигом добрым подвизался и течение совершил. Забывая заднее, он стремится к цели. Это дух того, кто не сдаётся."],["Подвизаться по правилам","Атлет не увенчивается, если не подвизается по правилам. Честная игра, уважение к сопернику и порядочность — тоже часть христианского свидетельства."],["Сила и ноги, как у оленя","Бог препоясывает нас силой и делает ноги наши, как у оленя. Физическое усилие можно проживать как благодарность за здоровье и полученные силы."],["Ходить с Богом","Ходьба — самое простое упражнение и одно из самых библейских: Енох ходил пред Богом, а Михей сводит веру к смиренному хождению с Ним. Прогулка может стать и временем молитвы."],["Укрепите ослабевшие колени","Для тех, кто только начинает, возвращается после травмы или чувствует себя без сил: Бог ободряет укрепить опустившиеся руки и выпрямить путь. Каждый маленький шаг важен."]],"work":[["Чтобы возделывать и хранить его","Ещё до грехопадения Бог поручает человеку сад, чтобы возделывать и хранить его. Труд — не наказание, а соработничество с Богом."],["Посмотри на муравья","Муравей трудится, хотя никто за ним не следит, и вовремя заготавливает пищу. Притчи призывают к постоянству и к победе над ленью маленькими шагами."],["Рука прилежных","Прилежание приносит плоды, а небрежность ведёт к бедности. Речь не о том, чтобы жить ради работы, а о том, чтобы хорошо делать своё дело."],["Как для Господа","«Всё, что делаете, делайте от души, как для Господа». Даже самая скромная работа обретает ценность, когда приносится Богу."],["Трудиться своими руками","Павел, делавший палатки, просит трудиться в тишине и есть свой хлеб. Честный труд даёт достоинство и свободу."],["Добродетельная жена","Притчи хвалят трудолюбивую и предприимчивую женщину, которая также открывает руку бедному. Добрый труд и щедрость идут рука об руку."],["Исправь дело рук наших","Если Господь не созиждет дома, напрасно трудятся строящие его. Мы просим Бога утвердить дело рук наших: человеческий труд нуждается в Его благословении."],["Справедливая плата","Закон велит платить работнику в тот же день, а Иаков обличает удержанную плату. Справедливость проживается и в труде."],["Иисус-плотник","Большую часть жизни Иисус трудился ремесленником в Назарете. Его сокровенная жизнь освящает повседневный труд."]],"give":[["Доброхотно дающего любит Бог","Кто сеет щедро, тот щедро и пожнёт. Бог смотрит не на количество, а на сердце: давать с радостью — уже дар для самого дающего."],["Сделали Мне","Накормить, одеть, посетить больного и узника: Иисус отождествляет Себя с малыми. Каждое дело служения — встреча с Ним."],["Милосердный самарянин","Тот, кто помогает, не спрашивает, свой ли раненый. Иисус заканчивает притчу поручением: «Иди, и ты поступай так же»."],["Две лепты вдовы","Две мелкие монеты стоят больше крупных пожертвований, потому что вдова отдала всё, что имела. Щедрость измеряется любовью, а не суммой."],["Блаженнее давать","Павел вспоминает эти слова Иисуса, а Притчи говорят, что благотворящий бедному даёт взаймы Господу. Давать — значит освобождать сердце."],["Умовение ног","Иисус умывает ноги ученикам и просит их делать то же. Кто хочет быть большим, да будет слугой: служение — это христианское величие."],["Страннолюбие","«Страннолюбия не забывайте», ибо некоторые, не зная, оказали гостеприимство ангелам. Открыть дом и стол — очень конкретный способ любить."],["Делиться имуществом","Первая община имела всё общее, и никто не нуждался. Апостол Иоанн просит любить не словом, а делом и истиною."]],"speech":[["Слова, которые созидают","Никакое гнилое слово да не исходит из уст ваших, а только доброе для назидания. Прежде чем говорить, стоит спросить себя, поможет ли то, что я скажу."],["Обуздать язык","Язык мал, как руль корабля, но может зажечь большой лес. Иаков просит последовательности: из одних уст не должны исходить благословение и проклятие."],["Скор на слышание, медлен на слова","Больше слушать, меньше говорить и не поддаваться гневу. Простой совет, который меняет многие разговоры."],["Кроткий ответ","Кроткий ответ отвращает гнев, а оскорбительное слово возбуждает ярость. Кроткий язык — древо жизни."],["Положи, Господи, охрану устам моим","Псалмопевец просит Бога охранять двери уст его и чтобы слова его были Ему угодны. Хорошая молитва для начала дня."],["Говорить правду","Да будет слово ваше: да, да; нет, нет. Отвергнув ложь, говорить истину ближнему — это строит доверие."],["Не судите","Прежде чем указывать на сучок в глазе брата, стоит увидеть бревно в своём. Говорить о других с милосердием — очень требовательная христианская привычка."],["Слово, приправленное солью","Слово ваше да будет всегда с благодатью, приправлено солью. Слово, сказанное вовремя, — что золотые яблоки в серебряных прозрачных сосудах."]],"joy":[["За всё благодарите","Всегда радуйтесь, непрестанно молитесь, за всё благодарите. Благодарность не отрицает проблем, но меняет взгляд на них."],["Только один вернулся поблагодарить","Из десяти исцелённых прокажённых только один вернулся поблагодарить. Иисус спрашивает о других: благодарность завершает дар."],["Благослови, душа моя, Господа","«Не забывай всех благодеяний Его». Помнить о полученном — начало благодарности."],["Сей день, который сотворил Господь","Каждый день — дар, чтобы радоваться ему. Благо возвещать утром милость Его и истину Его в ночи."],["Радуйтесь всегда в Господе","Павел пишет из темницы и повторяет: радуйтесь. Христианская радость зависит не от обстоятельств, а от того, что Господь близко."],["Я научился быть довольным","Павел знал и нужду, и изобилие, и научился быть довольным и тем, и другим. Его секрет: «Всё могу в укрепляющем меня Иисусе Христе»."],["Плод Духа","Любовь, радость, мир, долготерпение, благость, милосердие, вера, кротость, воздержание. Это привычки, которые Дух взращивает понемногу."],["Ибо вовек милость Его","Псалом снова и снова повторяет один и тот же припев, вспоминая дела Божии. Повторение благодарности запечатлевает её в сердце."]]},"ro":{"exer":[["Trupul, templu al Duhului","Grija de trup este o formă de recunoștință: nu este al nostru, este templu al Duhului Sfânt. Sfântul Pavel ne cheamă să-l aducem lui Dumnezeu ca jertfă vie. Mișcarea cu măsură face parte din această grijă."],["Alergați ca să câștigați","Pavel cunoștea jocurile din Corint: atleții se antrenează și se înfrânează în toate pentru o cunună trecătoare. Sportul învață disciplina, iar viața creștină o cere pentru o cunună netrecătoare."],["Exercițiul trupesc este folositor","Pavel nu disprețuiește exercițiul: spune că este de folos, deși evlavia este de folos la toate. Este o invitație de a ne ordona prioritățile: să antrenăm trupul fără să neglijăm sufletul."],["Să alergăm cu răbdare","Viața este o cursă de fond: trebuie să lepădăm ce ne îngreunează și să alergăm cu stăruință, cu privirea ațintită la Iisus. Nu viteza contează, ci să nu renunțăm."],["Călătoria am săvârșit","La sfârșitul vieții, Pavel spune că s-a luptat lupta cea bună și a săvârșit călătoria. Uitând cele din urmă, aleargă spre țintă. Este duhul celui care nu se dă bătut."],["A lupta după regulă","Atletul nu este încununat dacă nu s-a luptat după regulă. Jocul cinstit, respectul față de adversar și onestitatea fac parte și ele din mărturia creștină."],["Putere și picioare de cerb","Dumnezeu este Cel ce ne încinge cu putere și ne face picioarele ca ale cerbului. Efortul fizic poate fi trăit ca mulțumire pentru sănătatea și puterile primite."],["A umbla cu Dumnezeu","Mersul pe jos este exercițiul cel mai simplu și unul dintre cele mai biblice: Enoh a umblat cu Dumnezeu, iar Miheia rezumă credința în a umbla smerit cu El. O plimbare poate fi și o vreme de rugăciune."],["Întăriți genunchii slăbănogi","Pentru cine începe, revine după o accidentare sau se simte fără putere: Dumnezeu ne îndeamnă să întărim mâinile ostenite și să îndreptăm calea. Fiecare pas mic contează."]],"work":[["Ca să-l lucreze și să-l păzească","Încă dinainte de cădere, Dumnezeu încredințează omului grădina ca s-o lucreze și s-o păzească. Munca nu este o pedeapsă: este împreună-lucrare cu Dumnezeu."],["Privește la furnică","Furnica muncește fără să o supravegheze nimeni și își adună hrana la vreme. Pildele ne cheamă la statornicie și la biruirea lenei prin pași mici."],["Mâna celor harnici","Hărnicia aduce rod, iar delăsarea sărăcește. Nu e vorba să trăim pentru muncă, ci să facem bine ceea ce ne revine."],["Ca pentru Domnul","„Orice faceți, lucrați din toată inima, ca pentru Domnul.” Chiar și cea mai umilă sarcină capătă valoare când este adusă lui Dumnezeu."],["A munci cu propriile mâini","Pavel, care făcea corturi, ne cere să muncim în liniște și să ne câștigăm pâinea. Munca cinstită dă demnitate și libertate."],["Femeia virtuoasă","Pildele laudă o femeie harnică și întreprinzătoare, care își deschide mâna și către cel sărac. Munca bună și generozitatea merg împreună."],["Lucrul mâinilor noastre îndreptează-l","Dacă Domnul nu zidește casa, în zadar se ostenesc cei ce o zidesc. Îi cerem lui Dumnezeu să întărească lucrul mâinilor noastre: efortul omenesc are nevoie de binecuvântarea Lui."],["Plata dreaptă","Legea poruncește ca lucrătorul să fie plătit în aceeași zi, iar Iacov condamnă plata oprită. Dreptatea se trăiește și în muncă."],["Iisus, teslarul","Iisus și-a petrecut cea mai mare parte a vieții muncind ca meșteșugar în Nazaret. Viața Lui ascunsă sfințește munca de zi cu zi."]],"give":[["Pe cel ce dă cu voie bună îl iubește Dumnezeu","Cine seamănă cu dărnicie, cu dărnicie va și secera. Dumnezeu nu se uită la cantitate, ci la inimă: a da cu bucurie este deja un dar pentru cel ce dă."],["Mie Mi-ați făcut","A da de mâncare, a îmbrăca, a cerceta pe bolnav și pe cel din temniță: Iisus Se identifică cu cei mai mici. Orice faptă de slujire este o întâlnire cu El."],["Samarineanul milostiv","Cel ce ajută nu întreabă dacă rănitul este de-al lui. Iisus încheie pilda cu o sarcină: „Mergi și fă și tu asemenea.”"],["Cei doi bănuți ai văduvei","Doi bănuți valorează mai mult decât darurile mari, pentru că văduva a dat tot ce avea. Generozitatea se măsoară prin iubire, nu prin sumă."],["Mai fericit este a da","Pavel amintește acest cuvânt al lui Iisus, iar Pildele spun că cine miluiește pe sărac împrumută pe Domnul. A da eliberează inima."],["Spălarea picioarelor","Iisus spală picioarele ucenicilor și le cere să facă la fel. Cine vrea să fie mare să fie slujitor: slujirea este măreția creștină."],["Primirea de oaspeți","„Nu uitați iubirea de străini”, căci unii, fără să știe, au găzduit îngeri. A-ți deschide casa și masa este un mod foarte concret de a iubi."],["A împărți bunurile","Prima comunitate avea toate de obște și nimeni nu era în lipsă. Sfântul Ioan ne cere să iubim nu cu vorba, ci cu fapta și cu adevărul."]],"speech":[["Cuvinte care zidesc","Niciun cuvânt rău să nu iasă din gura voastră, ci numai cel bun spre zidire. Înainte de a vorbi, merită să mă întreb dacă ce voi spune ajută."],["A stăpâni limba","Limba este mică precum cârma unei corăbii, dar poate aprinde o pădure întreagă. Iacov cere consecvență: din aceeași gură n-ar trebui să iasă și binecuvântare, și blestem."],["Grabnic la ascultare, încet la vorbă","Să ascultăm mai mult, să vorbim mai puțin și să nu ne lăsăm duși de mânie. Un sfat simplu care schimbă multe conversații."],["Răspunsul blând","Un răspuns blând potolește mânia, iar un cuvânt aspru o aprinde. Limba blândă este pom al vieții."],["Pune, Doamne, strajă gurii mele","Psalmistul Îi cere lui Dumnezeu să păzească ușa buzelor lui și cuvintele lui să-I fie plăcute. Este o rugăciune bună pentru începutul zilei."],["A spune adevărul","Cuvântul vostru să fie: Da, da; Nu, nu. A lepăda minciuna și a grăi adevărul cu aproapele zidește încrederea."],["Nu judecați","Înainte de a arăta paiul din ochiul altuia, e bine să vedem bârna din ochiul nostru. A vorbi despre alții cu milă este un obicei creștin foarte exigent."],["Cuvinte dregate cu sare","Cuvântul vostru să fie totdeauna plin de har, dres cu sare. Un cuvânt spus la vreme este ca merele de aur în coșuleț de argint."]],"joy":[["Mulțumiți pentru toate","Bucurați-vă pururea, rugați-vă neîncetat, mulțumiți pentru toate. Recunoștința nu neagă problemele, dar schimbă privirea asupra lor."],["Doar unul s-a întors să mulțumească","Din zece leproși vindecați, doar unul s-a întors să mulțumească. Iisus îi caută pe ceilalți: recunoștința desăvârșește darul."],["Binecuvântează, suflete al meu, pe Domnul","„Nu uita toate binefacerile Lui.” A-ți aminti ce ai primit este începutul recunoștinței."],["Aceasta este ziua pe care a făcut-o Domnul","Fiecare zi este un dar în care să ne bucurăm. Bine este a vesti dimineața mila Lui și adevărul Lui noaptea."],["Bucurați-vă pururea în Domnul","Pavel scrie din temniță și repetă: bucurați-vă. Bucuria creștină nu depinde de împrejurări, ci de a ști că Domnul este aproape."],["Am învățat să fiu mulțumit","Pavel a cunoscut lipsa și belșugul și a învățat să fie mulțumit în amândouă. Secretul lui: „Toate le pot în Hristos, Cel ce mă întărește.”"],["Roada Duhului","Dragostea, bucuria, pacea, îndelunga-răbdare, bunătatea, facerea de bine, credința, blândețea, înfrânarea. Sunt obiceiuri pe care Duhul le face să crească încet-încet."],["Că în veac este mila Lui","Psalmul repetă iar și iar același refren, amintind lucrările lui Dumnezeu. Repetarea recunoștinței o întipărește în inimă."]]}};
for(const l in HBTX){if(TPTX[l])Object.assign(TPTX[l],HBTX[l])}
const HBX={"es":{"intro":{"exer":"Moverse, entrenar y competir también pueden vivirse desde la fe. La Biblia usa a menudo la imagen del atleta y del camino para hablar de la vida cristiana.","work":"El trabajo de cada día, bien hecho y ofrecido a Dios, es una forma de santidad. La Biblia habla de diligencia, de justicia y de descanso.","give":"Dar, servir y acoger son hábitos que nacen del amor de Dios. Jesús los vivió y nos pidió vivirlos con alegría.","speech":"Lo que decimos puede construir o herir. La Biblia da consejos muy prácticos para cuidar la lengua y hablar con verdad y caridad.","joy":"La gratitud y la alegría se pueden cultivar como un hábito diario. Los salmos y San Pablo nos enseñan a dar gracias en todo."},"names":{"exer":"Ejercicio y deporte","work":"Trabajo y diligencia","give":"Generosidad y servicio","speech":"Cuidar la palabra","joy":"Gratitud y alegría"},"sec":["Hábitos cristianos","Pequeños hábitos de cada día iluminados por la Biblia: el cuerpo, el trabajo, el servicio, la palabra y la gratitud.","Hábitos"]},"en":{"intro":{"exer":"Moving, training and competing can also be lived from faith. The Bible often uses the image of the athlete and of the road to speak about the Christian life.","work":"Everyday work, done well and offered to God, is a form of holiness. The Bible speaks of diligence, justice and rest.","give":"Giving, serving and welcoming are habits born of God's love. Jesus lived them and asked us to live them with joy.","speech":"What we say can build up or wound. The Bible gives very practical advice for guarding our tongue and speaking with truth and charity.","joy":"Gratitude and joy can be cultivated as a daily habit. The Psalms and Saint Paul teach us to give thanks in all things."},"names":{"exer":"Exercise and sport","work":"Work and diligence","give":"Generosity and service","speech":"Guarding our words","joy":"Gratitude and joy"},"sec":["Christian habits","Small everyday habits in the light of the Bible: the body, work, service, our words and gratitude.","Habits"]},"pt":{"intro":{"exer":"Mover-se, treinar e competir também se pode viver a partir da fé. A Bíblia usa muitas vezes a imagem do atleta e do caminho para falar da vida cristã.","work":"O trabalho de cada dia, bem feito e oferecido a Deus, é uma forma de santidade. A Bíblia fala de diligência, de justiça e de descanso.","give":"Dar, servir e acolher são hábitos que nascem do amor de Deus. Jesus viveu-os e pediu-nos que os vivêssemos com alegria.","speech":"O que dizemos pode construir ou ferir. A Bíblia dá conselhos muito práticos para guardar a língua e falar com verdade e caridade.","joy":"A gratidão e a alegria podem cultivar-se como um hábito diário. Os salmos e São Paulo ensinam-nos a dar graças em tudo."},"names":{"exer":"Exercício e desporto","work":"Trabalho e diligência","give":"Generosidade e serviço","speech":"Cuidar da palavra","joy":"Gratidão e alegria"},"sec":["Hábitos cristãos","Pequenos hábitos de cada dia iluminados pela Bíblia: o corpo, o trabalho, o serviço, a palavra e a gratidão.","Hábitos"]},"fr":{"intro":{"exer":"Bouger, s’entraîner et concourir peuvent aussi se vivre dans la foi. La Bible utilise souvent l’image de l’athlète et du chemin pour parler de la vie chrétienne.","work":"Le travail de chaque jour, bien fait et offert à Dieu, est une forme de sainteté. La Bible parle de diligence, de justice et de repos.","give":"Donner, servir et accueillir sont des habitudes qui naissent de l’amour de Dieu. Jésus les a vécues et nous demande de les vivre avec joie.","speech":"Ce que nous disons peut construire ou blesser. La Bible donne des conseils très concrets pour garder sa langue et parler avec vérité et charité.","joy":"La gratitude et la joie peuvent se cultiver comme une habitude quotidienne. Les psaumes et saint Paul nous apprennent à rendre grâce en tout."},"names":{"exer":"Exercice et sport","work":"Travail et diligence","give":"Générosité et service","speech":"Prendre soin de la parole","joy":"Gratitude et joie"},"sec":["Habitudes chrétiennes","De petites habitudes quotidiennes éclairées par la Bible : le corps, le travail, le service, la parole et la gratitude.","Habitudes"]},"it":{"intro":{"exer":"Muoversi, allenarsi e gareggiare si possono vivere anche a partire dalla fede. La Bibbia usa spesso l’immagine dell’atleta e del cammino per parlare della vita cristiana.","work":"Il lavoro di ogni giorno, fatto bene e offerto a Dio, è una forma di santità. La Bibbia parla di operosità, di giustizia e di riposo.","give":"Donare, servire e accogliere sono abitudini che nascono dall’amore di Dio. Gesù le ha vissute e ci ha chiesto di viverle con gioia.","speech":"Ciò che diciamo può costruire o ferire. La Bibbia dà consigli molto pratici per custodire la lingua e parlare con verità e carità.","joy":"La gratitudine e la gioia si possono coltivare come un’abitudine quotidiana. I salmi e san Paolo ci insegnano a rendere grazie in ogni cosa."},"names":{"exer":"Esercizio e sport","work":"Lavoro e operosità","give":"Generosità e servizio","speech":"Custodire la parola","joy":"Gratitudine e gioia"},"sec":["Abitudini cristiane","Piccole abitudini quotidiane illuminate dalla Bibbia: il corpo, il lavoro, il servizio, la parola e la gratitudine.","Abitudini"]},"de":{"intro":{"exer":"Bewegen, trainieren und Wettkämpfe können auch aus dem Glauben heraus gelebt werden. Die Bibel spricht oft im Bild des Athleten und des Weges vom christlichen Leben.","work":"Die tägliche Arbeit, gut getan und Gott dargebracht, ist eine Form der Heiligkeit. Die Bibel spricht von Fleiß, Gerechtigkeit und Ruhe.","give":"Geben, dienen und aufnehmen sind Gewohnheiten, die aus der Liebe Gottes kommen. Jesus hat sie gelebt und uns gebeten, sie mit Freude zu leben.","speech":"Was wir sagen, kann aufbauen oder verletzen. Die Bibel gibt sehr praktische Ratschläge, um die Zunge zu hüten und mit Wahrheit und Liebe zu sprechen.","joy":"Dankbarkeit und Freude lassen sich als tägliche Gewohnheit pflegen. Die Psalmen und Paulus lehren uns, in allem zu danken."},"names":{"exer":"Bewegung und Sport","work":"Arbeit und Fleiß","give":"Großzügigkeit und Dienst","speech":"Die Sprache hüten","joy":"Dankbarkeit und Freude"},"sec":["Christliche Gewohnheiten","Kleine tägliche Gewohnheiten im Licht der Bibel: der Körper, die Arbeit, das Dienen, das Wort und die Dankbarkeit.","Gewohnheiten"]},"el":{"intro":{"exer":"Η κίνηση, η προπόνηση και ο αγώνας μπορούν επίσης να βιωθούν μέσα από την πίστη. Η Βίβλος χρησιμοποιεί συχνά την εικόνα του αθλητή και του δρόμου για να μιλήσει για τη χριστιανική ζωή.","work":"Η καθημερινή εργασία, καλά καμωμένη και προσφερμένη στον Θεό, είναι μορφή αγιότητας. Η Βίβλος μιλά για επιμέλεια, δικαιοσύνη και ανάπαυση.","give":"Το να δίνεις, να διακονείς και να φιλοξενείς είναι συνήθειες που γεννιούνται από την αγάπη του Θεού. Ο Ιησούς τις έζησε και μας ζήτησε να τις ζούμε με χαρά.","speech":"Ό,τι λέμε μπορεί να οικοδομήσει ή να πληγώσει. Η Βίβλος δίνει πολύ πρακτικές συμβουλές για να φυλάμε τη γλώσσα και να μιλάμε με αλήθεια και αγάπη.","joy":"Η ευγνωμοσύνη και η χαρά μπορούν να καλλιεργηθούν ως καθημερινή συνήθεια. Οι Ψαλμοί και ο Απόστολος Παύλος μάς διδάσκουν να ευχαριστούμε για όλα."},"names":{"exer":"Άσκηση και αθλητισμός","work":"Εργασία και επιμέλεια","give":"Γενναιοδωρία και διακονία","speech":"Φυλακή της γλώσσας","joy":"Ευγνωμοσύνη και χαρά"},"sec":["Χριστιανικές συνήθειες","Μικρές καθημερινές συνήθειες στο φως της Βίβλου: το σώμα, η εργασία, η διακονία, ο λόγος και η ευγνωμοσύνη.","Συνήθειες"]},"ru":{"intro":{"exer":"Движение, тренировки и соревнования тоже можно проживать в вере. Библия часто использует образ атлета и пути, говоря о христианской жизни.","work":"Повседневный труд, хорошо исполненный и принесённый Богу, — это путь святости. Библия говорит о прилежании, справедливости и отдыхе.","give":"Давать, служить и принимать — привычки, которые рождаются из любви Божией. Иисус жил ими и просил нас жить ими с радостью.","speech":"Наши слова могут созидать или ранить. Библия даёт очень практичные советы, как хранить язык и говорить с правдой и любовью.","joy":"Благодарность и радость можно взращивать как ежедневную привычку. Псалмы и апостол Павел учат нас благодарить за всё."},"names":{"exer":"Движение и спорт","work":"Труд и прилежание","give":"Щедрость и служение","speech":"Хранить слово","joy":"Благодарность и радость"},"sec":["Христианские привычки","Маленькие ежедневные привычки в свете Библии: тело, труд, служение, слово и благодарность.","Привычки"]},"ro":{"intro":{"exer":"Mișcarea, antrenamentul și competiția pot fi trăite și din credință. Biblia folosește adesea imaginea atletului și a drumului pentru a vorbi despre viața creștină.","work":"Munca de fiecare zi, bine făcută și adusă lui Dumnezeu, este o formă de sfințenie. Biblia vorbește despre hărnicie, dreptate și odihnă.","give":"A da, a sluji și a primi pe alții sunt obiceiuri care se nasc din iubirea lui Dumnezeu. Iisus le-a trăit și ne-a cerut să le trăim cu bucurie.","speech":"Ceea ce spunem poate zidi sau răni. Biblia dă sfaturi foarte practice pentru a ne păzi limba și a vorbi cu adevăr și dragoste.","joy":"Recunoștința și bucuria pot fi cultivate ca un obicei zilnic. Psalmii și Sfântul Pavel ne învață să mulțumim pentru toate."},"names":{"exer":"Mișcare și sport","work":"Muncă și hărnicie","give":"Dărnicie și slujire","speech":"Paza cuvântului","joy":"Recunoștință și bucurie"},"sec":["Obiceiuri creștine","Mici obiceiuri zilnice în lumina Bibliei: trupul, munca, slujirea, cuvântul și recunoștința.","Obiceiuri"]}};
